                <th>Quantidade</th>
                <th>Valor Total</th>
                <th>Loja de Compra</th>
                <th>Código da Compra</th>
                <th>Forma de Pagamento</th>
                <th>Código de rastreio</th>
                <th>Status Encomenda</th>
                <th>  </th>
