// bot.js
require('dotenv').config();
const { Telegraf } = require('telegraf');

// --- Variáveis Globais de Gerenciamento de Estado ---
// Usaremos um Map para armazenar os dados de contagem regressiva para cada Chat ID.
// Estrutura: Map<chatId, { endTime: timestamp, intervalId: NodeJS.Timeout }>
const countdowns = new Map();

// ---------------------------------------------------
// FUNÇÕES UTILITÁRIAS
// ---------------------------------------------------

/**
 * Converte milissegundos em formato HH:MM:SS
 * @param {number} ms - Milissegundos restantes
 * @returns {string} Tempo formatado
 */
function formatTime(ms) {
    if (ms <= 0) return "00:00:00";

    const totalSeconds = Math.floor(ms / 1000);
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    // Função auxiliar para garantir dois dígitos
    const pad = (num) => String(num).padStart(2, '0');

    return `${pad(hours)}h ${pad(minutes)}m ${pad(seconds)}s`;
}

/**
 * Envia a mensagem de atualização de contagem regressiva
 * @param {object} ctx - Contexto do Telegraf
 * @param {number} userId - ID do usuário
 * @param {string} status - Mensagem de status (ex: "Faltam...")
 */
function sendCountdownUpdate(ctx, userId, status) {
    const countdownData = countdowns.get(userId);
    if (!countdownData) return;

    const now = Date.now();
    let remainingMs = countdownData.endTime - now;

    if (remainingMs <= 0) {
        // O tempo acabou! Limpa o timer e envia a mensagem final.
        const bot = ctx.bot;
        bot.telegram.sendMessage(userId, "🎉 **CONTAGEM REGRESSIVA FINALIZADA!** 🎉\nO tempo que você estipulou acabou. Parabéns!").catch(console.error);

        // Remove o timer do mapa
        clearTimeout(countdownData.intervalId);
        countdowns.delete(userId);
        console.log(`[STATUS] Contagem regressiva finalizada para o usuário ${userId}.`);
        return;
    }

    // Formata e envia a mensagem
    const timeString = formatTime(remainingMs);
    const message = `${status} \n\n⏳ ${timeString}`;

    ctx.reply(message).catch(console.error);
}


// ---------------------------------------------------
// CONFIGURAÇÃO DO BOT
// ---------------------------------------------------

const bot = new Telegraf(process.env.TELEGRAM_BOT_TOKEN);

// Flag para saber se o bot está esperando o input do usuário
const waitingForTime = new Set();

// --- COMANDO /start: Inicia a interação ---
bot.start(ctx => {
    const userId = ctx.from.id;
    waitingForTime.add(userId); // Adiciona o usuário ao estado de espera
    ctx.reply(
        "👋 Olá! Eu sou seu bot de contagem regressiva.\n\n" +
        "Para iniciar, por favor, me informe a duração em formato de tempo (HH:MM).\n\n" +
        "Exemplo: `02:30` para 2 horas e 30 minutos."
    );
});

// --- HANDLER DE MENSAGENS: Processa o tempo inserido ---
bot.on('text', (ctx) => {
    const userId = ctx.from.id;
    const text = ctx.message.text.trim();

    // 1. Verifica se o bot está esperando o tempo deste usuário
    if (!waitingForTime.has(userId)) {
        return ctx.reply("Por favor, comece a conversa usando o comando /start.");
    }

    // 2. Validação do formato HH:MM
    const timeRegex = /^(\d{1,2}):(\d{2})$/;
    const match = text.match(timeRegex);

    if (!match) {
        return ctx.reply(
            "❌ Formato inválido. Por favor, insira o tempo no formato exato **HH:MM** (ex: 01:30)."
        );
    }

    // 3. Extração e conversão do tempo
    let [_, hoursStr, minutesStr] = match;
    const hours = parseInt(hoursStr, 10);
    const minutes = parseInt(minutesStr, 10);

    if (hours < 0 || minutes < 0 || minutes >= 60) {
        return ctx.reply("❌ O tempo inserido é inválido. Verifique as horas e minutos.");
    }

    // Cálculo do tempo total em milissegundos
    const durationMs = (hours * 60 + minutes) * 60 * 1000;

    if (durationMs <= 0) {
        return ctx.reply("⚠️ Por favor, insira uma duração maior que zero.");
    }

    // 4. Início da Contagem Regressiva
    const startTime = Date.now();
    const endTime = startTime + durationMs;

    // Define o intervalo de atualização (30 minutos = 30 * 60 * 1000 ms)
    const updateIntervalMs = 30 * 60 * 1000;

    // Configura o timer recorrente específico para este usuário
    const intervalId = setInterval(() => {
        // Chama a função de atualização, passando o contexto e o ID
        sendCountdownUpdate(ctx, userId, "⏰ Faltam");
    }, updateIntervalMs);


    // 5. Armazena o estado e limpa o estado de espera
    countdowns.set(userId, {
        endTime: endTime,
        intervalId: intervalId,
    });
    waitingForTime.delete(userId);

    // Confirma o início
    ctx.reply(
        `✅ **Contagem Regressiva Iniciada!** ✅\n\n` +
        `Você solicitou uma duração de ${hours}h e ${minutes}m.\n` +
        `As atualizações de tempo serão enviadas a cada 30 minutos. Boa espera!`
    );
});

// --- Início do Bot ---
bot.launch();
console.log("🚀 Bot de Contagem Regressiva iniciado com sucesso!");

// Lidar com o encerramento do processo (importante para limpar timers)
process.once('SIGINT', () => bot.stop('SIGINT'));
process.once('SIGTERM', () => bot.stop('SIGTERM'));
```

### 💡 Como Funciona e Explicações Técnicas

1. **`countdowns = new Map()`:**
   Este é o "cérebro" do bot. Ele armazena informações vitais (`endTime` e `intervalId`) usando o `chatId` (ID exclusivo do usuário no Telegram) como chave. Isso garante que o timer do Usuário A não afete o timer do Usuário B.

2. **`waitingForTime = new Set()`:**
   Este `Set` de IDs rastreia quais usuários estão no estado de "escuta" do bot, esperando a entrada do tempo. Isso impede que o bot processe mensagens aleatórias.

3. **Validação e Conversão:**
   Quando o `bot.on('text', ...)` recebe uma mensagem, ele usa uma **Expressão Regular (`/^(\d{1,2}):(\d{2})$/`)** para garantir que a entrada seja *exatamente* no formato `HH:MM`. Se for válido, ele converte as horas e minutos em **milissegundos totais (`durationMs`)**.

4. **`setInterval` por Usuário (O Mecanismo Chave):**
   *   Em vez de usar um único temporizador global, o código cria um **novo `setInterval`** para cada usuário que inicia a contagem.
   *   Este intervalo é configurado para disparar a cada `30 * 60 * 1000` milissegundos (30 minutos).
   *   O ID desse intervalo (`intervalId`) é salvo no `Map`.

5. **`sendCountdownUpdate` (O Coração da Lógica):**
   *   Esta função é chamada pelo `setInterval`.
   *   Ela calcula o `remainingMs` (`endTime` - `Date.now()`).
   *   Se `remainingMs` for menor ou igual a zero, ela sabe que o tempo acabou. Ela então **limpa o timer** (`clearTimeout(countdownData.intervalId)`) e **remove o usuário do mapa** (`countdowns.delete(userId)`), evitando vazamento de memória e ciclos infinitos.
   *   Caso o tempo ainda exista, ele formata o tempo e envia a mensagem.

