/**
 * @brief Calcula o hash Keccak-512 de um arquivo.
 * @param filePath Caminho completo do arquivo.
 * @return O hash em formato hexadecimal.
 */
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    try {
        CryptoPP::FileSource(filePath.c_str(), true,
            new CryptoPP::HashFilter(hash,
                new CryptoPP::HexEncoder(
                    new CryptoPP::StringSink(digest), true)));
    } catch (const CryptoPP::Exception& e) {
        std::cerr << "Erro ao processar o arquivo " << filePath << ": " << e.what() << std::endl;
        return ""; // Retorna string vazia em caso de falha
    }
    return digest;
}

/**
 * @brief Função auxiliar para dividir uma string por um delimitador (e.g., vírgula).
 */
std::vector<int> parseInput(const std::string& input) {
    std::vector<int> selections;
    std::stringstream ss(input);
    std::string segment;

    while (std::getline(ss, segment, ',')) {
        try {
            // Remove espaços em branco antes de converter
            segment.erase(0, segment.find_first_not_of(' '));
            segment.erase(segment.find_last_not_of(' ') + 1);

            // Tenta converter a parte em um número
            size_t pos;
            int number = std::stoi(segment, &pos);

            if (pos == segment.length()) { // Garante que toda a string foi um número
                selections.push_back(number);
            }
        } catch (...) {
            // Ignora segmentos que não são números
        }
    }
    return selections;
}


